<#
  Fix-ReverseGeocodeFallback.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  What this fixes:

  PICKUP/DROPOFF SOMETIMES RESOLVING TO RAW COORDINATES ("12.0047, 8.5371")
  INSTEAD OF A LOCATION NAME
  Root cause: reverseGeocodeMapbox in src\utils\mapbox.js fell back to
  printing raw lat/lng text on ANY failure - a non-OK API response, an
  empty result set, or a flat 6-second timeout. On Kano's patchier mobile
  networks, that timeout was the most common trigger. A user has no way
  to interpret "12.0047, 8.5371" as a place.

  Fixed by:
    - Retrying once with a broader Mapbox type filter (in case the strict
      types=address,poi,neighborhood,locality filter excluded a real
      match) before giving up.
    - Bumping the per-attempt timeout from 6s to 8s to give slow
      connections more room.
    - Replacing the raw-coordinate fallback with a plain "Pinned location"
      string if both attempts fail. The map pin itself still holds the
      real lat/lng - only the human-readable label was ever the problem.

  Only src\utils\mapbox.js is touched. Nothing else in this file changed.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS, no BOM-injection risk). Backs up the
  existing file to .fix-backup-reverse-geocode\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-ReverseGeocodeFallback.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-reverse-geocode"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\utils"))) {
    Write-Host "ERROR: src\utils not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying reverse-geocode coordinate-fallback fix:" -ForegroundColor Cyan

$b64_MAPBOX = ""
Write-FileFromBase64 "src\utils\mapbox.js" $b64_MAPBOX

Write-Host "`nDone. Backup saved under .fix-backup-reverse-geocode\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
